#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>a(n);
for(int i=0;i<n;++i)scanf("%lld",&a[i]);
bool first=true;
for(int i=0;i<n;){
int j=i;while(j+1<n&&a[j+1]==a[j]+1)++j;
if(!first)printf(" ");first=false;
if(i==j)printf("%lld",a[i]);else printf("%lld->%lld",a[i],a[j]);
i=j+1;}
printf("\n");return 0;}

